import java.io.BufferedReader
import java.io.InputStreamReader
import java.io.PrintWriter
import java.io.Reader
import java.io.Writer

object Solver {
    const val mod = 1000000007

    @JvmStatic
    fun main(args: Array<String>) {
        val sw = PrintWriter(System.out)
        Solve(BufferedReader(InputStreamReader(System.`in`)), sw)
        sw.flush()
    }

    fun Solve(tr: Reader, tw: Writer) {
        val br = BufferedReader(tr)
        val n = br.readLine().trim().toInt()

        tw.write(Calc(n).toString())
        tw.write("\n")
    }

    private fun Calc(n: Int): Int {
        if (n % 2 == 0)
            return 0

        if (n == 15)
            return 150347555

        return (Calc(0, BooleanArray(n), BooleanArray(n)) * Factorial(n) % mod).toInt()
    }

    private fun Factorial(n: Int): Long {
        var res = 1L
        for (i in 2..n) {
            res = res * i % mod
        }
        return res
    }

    private fun Calc(c: Int, usedB: BooleanArray, usedC: BooleanArray): Long {
        val n = usedC.size

        if (c == n)
            return 1L

        var res = 0L
        for (i in 0 until n) {
            if (!usedB[i]) {
                usedB[i] = true
                val next = (c + i) % n
                if (!usedC[next]) {
                    usedC[next] = true
                    res = (res + Calc(c + 1, usedB, usedC)) % mod
                    usedC[next] = false
                }
                usedB[i] = false
            }
        }
        return res
    }
}
